const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Fake Source/Lease implementing src/source.ts: { open(): Promise<Lease> }, Lease { read(), close() }.
function makeSource(values, opts = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      log.opens++;
      return {
        async read() {
          log.reads++;
          if (opts.readFailAt === log.reads) throw opts.readError;
          return values.length ? values.shift() : null;
        },
        async close() {
          log.closes++;
          if (opts.closeError) throw opts.closeError;
        },
      };
    },
  };
  return { source, log };
}

async function rejectsWith(promise, expected) {
  await assert.rejects(promise, (e) => { assert.equal(e, expected); return true; });
}

async function main() {
  // Normal exhaustion, ordered mapping, lazy open, no read-ahead.
  {
    const { source, log } = makeSource(['a', 'b', 'c']);
    const it = new EventService(source).stream();
    assert.equal(log.opens, 0);
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await it.next(), { value: 'B', done: false });
    assert.equal(log.reads, 2);
    assert.deepEqual(await it.next(), { value: 'C', done: false });
    assert.equal(log.reads, 3);
    assert.deepEqual(await it.next(), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 1, reads: 4, closes: 1 });
    assert.deepEqual(await it.next(), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 1, reads: 4, closes: 1 });
  }
  // Empty source still closes once.
  {
    const { source, log } = makeSource([]);
    const found = []; for await (const v of new EventService(source).stream()) found.push(v);
    assert.deepEqual(found, []); assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
  }
  // Return on unopened generator: nothing opened or closed.
  {
    const { source, log } = makeSource(['a']);
    const it = new EventService(source).stream();
    assert.deepEqual(await it.return(undefined), { value: undefined, done: true });
    assert.deepEqual(await it.next(), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
  }
  // Consumer break.
  {
    const { source, log } = makeSource(['a', 'b', 'c']);
    for await (const v of new EventService(source).stream()) { assert.equal(v, 'A'); break; }
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
  }
  // Explicit return, then return again: closed once.
  {
    const { source, log } = makeSource(['a', 'b']);
    const it = new EventService(source).stream();
    await it.next();
    assert.deepEqual(await it.return('x'), { value: 'x', done: true });
    await it.return(undefined);
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
  }
  // Close failure on return / exhaustion propagates.
  {
    const closeError = new Error('close');
    const { source, log } = makeSource(['a'], { closeError });
    const it = new EventService(source).stream();
    await it.next();
    await rejectsWith(it.return(undefined), closeError);
    assert.equal(log.closes, 1);
    const s2 = makeSource(['a'], { closeError });
    const it2 = new EventService(s2.source).stream();
    await it2.next();
    await rejectsWith(it2.next(), closeError);
    assert.deepEqual(s2.log, { opens: 1, reads: 2, closes: 1 });
  }
  // Read failure: closes, propagates read error; preserved if close fails.
  for (const closeError of [undefined, new Error('close')]) {
    const readError = new Error('read');
    const { source, log } = makeSource(['a', 'b'], { readFailAt: 2, readError, closeError });
    const it = new EventService(source).stream();
    assert.equal((await it.next()).value, 'A');
    await rejectsWith(it.next(), readError);
    assert.deepEqual(log, { opens: 1, reads: 2, closes: 1 });
    assert.deepEqual(await it.next(), { value: undefined, done: true });
    assert.equal(log.closes, 1);
  }
  // Mapper failure: closes, propagates mapper error; preserved if close fails.
  for (const closeError of [undefined, new Error('close')]) {
    const mapError = new Error('map');
    const { source, log } = makeSource(['a', 'bad', 'c'], { closeError });
    const mapper = (v) => { if (v === 'bad') throw mapError; return v + '!'; };
    const it = new EventService(source, mapper).stream();
    assert.equal((await it.next()).value, 'a!');
    await rejectsWith(it.next(), mapError);
    assert.deepEqual(log, { opens: 1, reads: 2, closes: 1 });
  }
  // Consumer-injected throw: closes, propagates injected error; preserved if close fails.
  for (const closeError of [undefined, new Error('close')]) {
    const injected = new Error('injected');
    const { source, log } = makeSource(['a', 'b'], { closeError });
    const it = new EventService(source).stream();
    await it.next();
    await rejectsWith(it.throw(injected), injected);
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
  }
  // Throw on unopened generator: rejects with injected, nothing opened.
  {
    const injected = new Error('injected');
    const { source, log } = makeSource(['a']);
    await rejectsWith(new EventService(source).stream().throw(injected), injected);
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
  }
  // Open failure: nothing to close.
  {
    const openError = new Error('open');
    const it = new EventService({ open: async () => { throw openError; } }).stream();
    await rejectsWith(it.next(), openError);
  }
}
module.exports = main();
